<?php
$stages=array('submitted'=>0,'verification'=>0,'scheduled'=>0,'testing'=>0,'finished'=>0);
$unit_map=array();$service_codes=array();$terminal_labels=array();$can_cancel=TRUE;
foreach ($items as $entry) {
    $unit_map[(int)$entry->id]=$entry;if (!in_array($entry->item_status,array('submitted','revision'),TRUE)) $can_cancel=FALSE;
    $service_codes[]=$entry->service_type ?: $request->service_type;
    if (metro_is_terminal($entry->item_status)) {
        $stages['finished']++;
        $outcome=status_label($entry->item_status);
        $terminal_labels[$outcome]=($terminal_labels[$outcome]??0)+1;
    }
    elseif ($entry->item_status==='scheduled') $stages['scheduled']++;
    elseif (in_array($entry->item_status,array('testing','review'),TRUE)) $stages['testing']++;
    elseif (in_array($entry->item_status,array('verification','revision'),TRUE)) $stages['verification']++;
    else $stages['submitted']++;
}
?>
<div class="page-heading"><div><a class="back-link" href="<?= site_url('permohonan') ?>">← Semua permohonan</a><div class="eyebrow">Detail permohonan</div><h1><?= e($request->request_no) ?></h1><p><?= e(service_types_label(implode(',',$service_codes))) ?> · <?= e(tanggal_id($request->submitted_at,TRUE)) ?> · <?= e($request->full_name) ?></p></div><a class="button outline" href="<?= site_url('permohonan/'.$request->id.'/bukti') ?>" target="_blank" rel="noopener">Preview bukti order PDF</a></div>
<?php if ($request->booking_code): ?><div class="booking-code-banner" role="status"><div><small>Kode booking</small><strong><?= e($request->booking_code) ?></strong><span>Simpan kode ini untuk melacak status dari beranda.</span></div><a class="button outline" href="<?= site_url() ?>#lacak-status">Lacak status →</a></div><?php endif; ?>
<section class="request-progress" aria-label="Tahapan status UTTP">
<?php foreach (array('submitted'=>'Dikirim','verification'=>'Kaji ulang','scheduled'=>'Terjadwal','testing'=>'Pengujian','finished'=>'Selesai') as $stage=>$label): ?><div class="request-progress-step"><span class="request-progress-dot"></span><strong><?= e($label) ?></strong><small><?= (int)$stages[$stage] ?> UTTP</small><?php if ($stage==='finished' && $terminal_labels): ?><span class="request-progress-outcomes"><?php foreach ($terminal_labels as $outcome=>$count): ?><span><?= e($outcome) ?> <?= (int)$count ?></span><?php endforeach; ?></span><?php endif; ?></div><?php endforeach; ?>
</section>
<div class="detail-grid"><div><section class="card detail-card"><div class="section-heading compact"><div><div class="eyebrow">Pelacakan</div><h2>Status per unit</h2></div><span class="badge <?= status_class($request->request_status) ?>"><?= e(status_label($request->request_status)) ?></span></div>
<?php foreach ($items as $item): ?>
<details class="unit-row applicant-unit"><summary class="unit-head"><div><strong><?= (int)$item->unit_sequence ?> · <?= e($item->uttp_name) ?></strong><small><?= e($item->owner_name) ?><?= $item->brand?' · '.e($item->brand):'' ?><?= $item->capacity?' · '.e($item->capacity):'' ?></small><small><?= e(implode(' · ',array_filter(array($item->media?'Media '.$item->media:NULL,$item->nozzle_no?'Nozzle '.$item->nozzle_no:NULL,$item->dispenser_no?'Dispenser '.$item->dispenser_no:NULL,$item->manufacture_year?'Tahun '.$item->manufacture_year:NULL,$item->flow_rate?'Qmax/Qmin '.$item->flow_rate:NULL,$item->readability?'Daya baca '.$item->readability:NULL)))) ?></small></div><span class="badge <?= status_class($item->item_status) ?>"><?= e(status_label($item->item_status)) ?></span><span class="unit-expand-icon" aria-hidden="true">⌄</span><div class="progress"><span style="width:<?= metro_is_terminal($item->item_status)?100:(in_array($item->item_status,array('testing','review'),TRUE)?80:($item->item_status==='scheduled'?60:($item->item_status==='verification'?40:20))) ?>%"></span></div></summary>
<div class="applicant-unit-body"><p class="applicant-status-message"><?= e(status_description($item->item_status) ?: status_label($item->item_status)) ?></p><dl><div><dt>Jenis layanan</dt><dd><?= e(master_label('service_type',$item->service_type ?: $request->service_type)) ?></dd></div><div><dt>Spesifikasi</dt><dd><?= e(implode(' · ',array_filter(array($item->brand,$item->type_name,$item->capacity,$item->media?'Media '.$item->media:NULL,$item->nozzle_no?'Nozzle '.$item->nozzle_no:NULL,$item->dispenser_no?'Dispenser '.$item->dispenser_no:NULL,$item->manufacture_year?'Tahun '.$item->manufacture_year:NULL,$item->flow_rate?'Qmax/Qmin '.$item->flow_rate:NULL,$item->readability?'Daya baca '.$item->readability:NULL)))) ?></dd></div><?php if ($item->service_address): ?><div><dt>Lokasi UTTP</dt><dd><?= e($item->service_address) ?><?php if ($item->latitude!==NULL && $item->longitude!==NULL): ?> · <a href="<?= e('https://www.openstreetmap.org/?mlat='.$item->latitude.'&mlon='.$item->longitude.'#map=16/'.$item->latitude.'/'.$item->longitude) ?>" target="_blank" rel="noopener noreferrer">Lihat peta ↗</a><?php endif; ?></dd></div><?php endif; ?></dl>
<?php foreach ($documents as $doc): $same_unit=(int)$doc->request_item_id===(int)$item->id;$shared=FALSE;
if (!$same_unit && $item->certificate_scope==='order') foreach ($items as $source) if ((int)$source->id===(int)$doc->request_item_id && $source->certificate_scope==='order') {$shared=TRUE;break;}
if ($doc->document_type==='skhp' && ($same_unit || $shared) && metro_is_valid($item->item_status)): ?><a class="download-link" href="<?= site_url('dokumen/'.$doc->id.'?inline=1') ?>" target="_blank" rel="noopener">Preview SKHP · <?= e($doc->original_name) ?></a><?php endif; endforeach; ?></div></details>
<?php endforeach; ?></section>
<section class="card detail-card"><h2>Riwayat proses</h2><?php foreach ($history as $h): if ($h->visibility!=='applicant') continue;$history_unit=$unit_map[(int)$h->request_item_id]??NULL; ?><div class="timeline-row"><span class="timeline-dot <?= status_class($h->to_status) ?>"></span><div><strong><?= $history_unit?(int)$history_unit->unit_sequence.' · '.e($history_unit->uttp_name).' · ':'' ?><?= e(status_label($h->to_status)) ?></strong><small><?= $history_unit?e(implode(' · ',array_filter(array($history_unit->brand,$history_unit->type_name,$history_unit->capacity,$history_unit->media?'Media '.$history_unit->media:NULL,$history_unit->nozzle_no?'Nozzle '.$history_unit->nozzle_no:NULL,$history_unit->dispenser_no?'Dispenser '.$history_unit->dispenser_no:NULL,$history_unit->manufacture_year?'Tahun '.$history_unit->manufacture_year:NULL,$history_unit->flow_rate?'Qmax/Qmin '.$history_unit->flow_rate:NULL,$history_unit->readability?'Daya baca '.$history_unit->readability:NULL)))).' · ':'' ?><?= e(tanggal_id($h->created_at,TRUE)) ?><?= $h->note?' · '.e($h->note):'' ?></small></div></div><?php endforeach; ?></section></div>
<aside><section class="card detail-card"><h2>Ringkasan</h2><dl class="summary"><div><dt>Pemohon</dt><dd><?= e($request->full_name) ?></dd></div><div><dt>Alamat layanan</dt><dd><?= e($request->service_address) ?></dd></div><div><dt>Jumlah unit</dt><dd><?= count($items) ?></dd></div></dl></section>
<section class="card detail-card"><h2>Dokumen</h2><?php foreach ($documents as $doc): if ($doc->document_type!=='application_letter') continue; ?><a class="document-link" href="<?= site_url('dokumen/'.$doc->id.'?inline=1') ?>" target="_blank" rel="noopener">Preview permohonan · <?= e($doc->original_name) ?></a><?php endforeach; ?></section>
<?php if ($can_cancel && !$request->cancelled_at && !$request->completed_at && $can_revise): ?><section class="card detail-card"><h2>Batalkan permohonan</h2><p class="muted">Pembatalan tersedia sebelum petugas memulai proses kaji ulang.</p><form method="post" action="<?= site_url('permohonan/'.$request->id.'/batal') ?>" onsubmit="return confirm('Batalkan permohonan ini?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><label>Alasan pembatalan<textarea name="reason" minlength="5" maxlength="500" required></textarea></label><button class="button outline" type="submit">Batalkan permohonan</button></form></section><?php endif; ?>
<?php if ($needs_revision && $can_revise && $this->metro->can($current_user->id,'self.requests.revise')): ?><section class="card detail-card"><h2>Perbaiki berkas</h2><p class="muted">Unggah surat permohonan PDF yang telah diperbaiki.</p><form method="post" enctype="multipart/form-data" action="<?= site_url('permohonan/'.$request->id.'/perbaiki') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><input type="file" name="application_letter" accept="application/pdf,.pdf" required><button class="button primary full" type="submit">Kirim perbaikan</button></form></section><?php endif; ?>
<?php if (in_array($request->request_status,array('valid','completed','closed'),TRUE) && !$feedback && (int)$request->user_id===(int)$current_user->id && $this->metro->can($current_user->id,'self.requests.feedback')): ?><section class="card detail-card"><h2>Kritik dan saran</h2><form method="post" action="<?= site_url('permohonan/'.$request->id.'/umpan-balik') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><label>Nilai layanan<select name="rating" required><option value="">Pilih nilai</option><?php for ($i=1;$i<=5;$i++): ?><option value="<?= $i ?>"><?= $i ?> bintang</option><?php endfor; ?></select></label><label>Masukan<textarea name="comment" rows="3" maxlength="2000"></textarea></label><button class="button primary full" type="submit">Kirim masukan</button></form></section><?php endif; ?></aside></div>
